begin;
with j as (select * from jsonb_to_recordset($law7d0003$[{"code_id":"APK_RF","article_number":"178","version_date":"2002-07-24","article_text":"1. Арбитражный суд, принявший решение, до вступления этого решения в законную силу по своей инициативе или по заявлению лица, участвующего в деле, вправе принять дополнительное решение в случае, если:\n\n1) по какому-либо требованию, в отношении которого лица, участвующие в деле, представили доказательства, судом не было принято решение;\n\n2) суд, разрешив вопрос о праве, не указал в решении размер присужденной денежной суммы, подлежащее передаче имущество или не указал действия, которые обязан совершить ответчик;\n\n3) судом не разрешен вопрос о судебных расходах.\n\n2. Вопрос о принятии арбитражным судом дополнительного решения разрешается в судебном заседании. Лица, участвующие в деле, извещаются о времени и месте судебного заседания. Неявка надлежащим образом извещенных лиц не препятствует рассмотрению вопроса о принятии дополнительного решения.\n\n3. Дополнительное решение принимается по правилам, установленным в настоящей главе.\n\n4. В случае отказа в принятии дополнительного решения выносится определение.\n\n5. Дополнительное решение арбитражного суда и определение арбитражного суда об отказе в принятии дополнительного решения могут быть обжалованы.","article_title":"Статья 178. Дополнительное решение","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"24d16dd8487eb02d8091a6312d3f2580a7959c187e96000755fa4f9eae1b7616"},{"code_id":"APK_RF","article_number":"179","version_date":"2002-07-24","article_text":"1. В случае неясности решения арбитражный суд, принявший это решение, по заявлению лица, участвующего в деле, судебного пристава-исполнителя, других исполняющих решение арбитражного суда органа, организации вправе разъяснить решение без изменения его содержания.\n\n2. Разъяснение решения допускается, если оно не приведено в исполнение и не истек срок, в течение которого решение может быть принудительно исполнено.\n\n3. Арбитражный суд, принявший решение, по заявлению лица, участвующего в деле, судебного пристава-исполнителя, других исполняющих решение арбитражного суда органа, организации или по своей инициативе вправе исправить допущенные в решении описки, опечатки и арифметические ошибки без изменения его содержания.","article_title":"Статья 179. Разъяснение решения. Исправление описок, опечаток и арифметических ошибок","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"06cfafe55c4d5c1bce7f9682b77241e5f860798d474746bfd080e708ce8b62e6"},{"code_id":"APK_RF","article_number":"18","version_date":"2002-07-24","article_text":"1) заявленного и удовлетворенного в порядке, установленном настоящим Кодексом, самоотвода или отвода судьи, арбитражного заседателя;\n\n2) длительного отсутствия судьи, арбитражного заседателя ввиду болезни, отпуска, пребывания на учебе, нахождения в служебной командировке.\n\n(Статья в редакции Федерального закона от 27.07.2010 № 228-ФЗ)","article_title":"Статья 18. Формирование состава суда","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f22af3542bac4229a7b8375dff4f041426c51e1b21df47ed6b63ff02452cf1b9"},{"code_id":"APK_RF","article_number":"180","version_date":"2002-07-24","article_text":"(Наименование в редакции Федерального закона от 02.03.2016 № 47-ФЗ)\n\n1. Решение арбитражного суда первой инстанции, за исключением решений, указанных в частях 2 и 3 настоящей статьи, вступает в законную силу по истечении месячного срока со дня его принятия, если не подана апелляционная жалоба. В случае подачи апелляционной жалобы решение, если оно не отменено и не изменено, вступает в законную силу со дня принятия постановления арбитражного суда апелляционной инстанции.","article_title":"Статья 180. Вступление в законную силу решения, судебного приказа","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cdfeed76172280c8e02c26e1c3afa125b25ae5087ff01cc110ed664e8fbf014d"},{"code_id":"APK_RF","article_number":"181","version_date":"2002-07-24","article_text":"(Статья в редакции Федерального закона от 27.07.2010 № 228-ФЗ)","article_title":"Статья 181. Обжалование решения арбитражного суда","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0dcb8aa602e92c57e5152bcb95c6af95dbb96cc7240b502c878aacb65ed6813c"},{"code_id":"APK_RF","article_number":"182","version_date":"2002-07-24","article_text":"(Наименование в редакции Федерального закона от 02.03.2016 № 47-ФЗ)\n\n1. Решение арбитражного суда приводится в исполнение после вступления его в законную силу, за исключением случаев немедленного исполнения, в порядке, установленном настоящим Кодексом и иными федеральными законами, регулирующими вопросы исполнительного производства.\n\nКопии определения направляются лицам, участвующим в деле, не позднее следующего дня после дня его вынесения.","article_title":"Статья 182. Исполнение решения, судебного приказа","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c8a97fbb5924a665e6172ad474d06ecd777e77361b53cbf8ccd6463f605a9777"},{"code_id":"APK_RF","article_number":"183","version_date":"2002-07-24","article_text":"1. По заявлению взыскателя или должника арбитражный суд первой инстанции, рассмотревший дело, производит индексацию присужденных судом денежных сумм на день исполнения решения суда.\n\nЕсли иное не предусмотрено федеральным законом, присужденные денежные суммы индексируются со дня вынесения решения суда или, если решением суда предусмотрена выплата присужденной денежной суммы в предстоящем периоде, с момента, когда такая выплата должна была быть произведена.\n\nЕсли иное не предусмотрено федеральным законом или договором, для индексации используется официальная статистическая информация об индексе потребительских цен (тарифов) на товары и услуги в Российской Федерации, размещаемая на официальном сайте федерального органа исполнительной власти, осуществляющего функции по формированию официальной статистической информации о социальных, экономических, демографических, экологических и других общественных процессах в Российской Федерации, в информационно-телекоммуникационной сети \"Интернет\".\n\nЗаявление об индексации присужденных судом денежных сумм может быть подано в срок, не превышающий одного года со дня исполнения должником судебного акта. При наличии уважительных причин указанный срок может быть восстановлен арбитражным судом в порядке, предусмотренном статьей 117 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 01.04.2025 № 54-ФЗ)\n\n(Часть в редакции Федерального закона от 11.06.2022 № 177-ФЗ)\n\nПо результатам рассмотрения заявления выносится определение.","article_title":"Статья 183. Индексация присужденных денежных сумм","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2a74c81ef6fc8e25030e49acd98ddb20aa1435b8df238680667d5bc4d27f8b3a"},{"code_id":"APK_RF","article_number":"184","version_date":"2002-07-24","article_text":"1. Арбитражный суд выносит определения в случаях, предусмотренных настоящим Кодексом, и в других случаях по вопросам, требующим разрешения в ходе судебного разбирательства.\n\n2. Определение выносится арбитражным судом в виде отдельного судебного акта или протокольного определения.\n\nОпределение арбитражного суда в виде отдельного судебного акта выполняется в форме электронного документа. При отсутствии в арбитражном суде технической возможности для выполнения определения в форме электронного документа определение выполняется на бумажном носителе.\n\nПри выполнении определения в форме электронного документа дополнительно выполняется экземпляр данного определения на бумажном носителе.\n\nИзготовление определения арбитражного суда в виде отдельного судебного акта в полном объеме может быть отложено на срок, не превышающий десяти дней. Дата изготовления определения в полном объеме считается датой вынесения определения. (Дополнение абзацем - Федеральный закон от 25.12.2023 № 667-ФЗ)\n\n(Часть в редакции Федерального закона от 23.06.2016 № 220-ФЗ)\n\n3. Определение в виде отдельного судебного акта арбитражный суд выносит во всех случаях, если настоящим Кодексом предусмотрена возможность обжалования определения отдельно от обжалования судебного акта, которым заканчивается рассмотрение дела по существу.\n\nВ других случаях арбитражный суд вправе вынести определение как в виде отдельного судебного акта, так и в виде протокольного определения.\n\n4. Определение в виде отдельного судебного акта арбитражный суд выносит в условиях, обеспечивающих тайну совещания судей, по правилам, установленным для принятия решения.\n\n5. Протокольное определение может быть вынесено арбитражным судом без удаления из зала судебного заседания. В случае, если дело рассматривается в коллегиальном составе, судьи совещаются по вопросам, связанным с вынесением такого определения, на месте, в зале судебного заседания. Протокольное определение объявляется устно и заносится в протокол судебного заседания.","article_title":"Статья 184. Вынесение арбитражным судом определений","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ed3dce08b6f2b2c3f530a53813a8f59725a3085fc619728f2f7897274fb6470b"},{"code_id":"APK_RF","article_number":"185","version_date":"2002-07-24","article_text":"1. В определении должны быть указаны:\n\n1) дата и место вынесения определения;\n\n2) наименование арбитражного суда, состав суда, фамилия лица, которое вело протокол судебного заседания;\n\n3) наименование и номер дела;\n\n4) наименования лиц, участвующих в деле;\n\n5) вопрос, по которому выносится определение;\n\n6) мотивы, по которым арбитражный суд пришел к своим выводам, принял или отклонил доводы лиц, участвующих в деле, со ссылкой на законы и иные нормативные правовые акты;\n\n7) вывод по результатам рассмотрения судом вопроса;\n\n8) порядок и срок обжалования определения.\n\nОпределение, выносимое в виде отдельного судебного акта, подписывается судьей или составом арбитражного суда, вынесшими это определение.\n\n2. В протокольном определении должны быть указаны вопрос, по которому выносится определение, мотивы, по которым суд пришел к своим выводам, и вывод по результатам рассмотрения вопроса.","article_title":"Статья 185. Содержание определения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"24296633569fa6d0bfc3e53b7a115d26bbb77084659cccf684e5f5f3973e53f2"},{"code_id":"APK_RF","article_number":"186","version_date":"2002-07-24","article_text":"По ходатайству указанных лиц копии определения, вынесенного в виде отдельного судебного акта, на бумажном носителе могут быть направлены им в пятидневный срок со дня поступления соответствующего ходатайства в арбитражный суд заказным письмом с уведомлением о вручении или вручены им под расписку.\n\n(Статья в редакции Федерального закона от 23.06.2016 № 220-ФЗ)","article_title":"Статья 186. Направление определения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7aea92f8ff702dc7acbede80c0203e30c9e7ecba1963b9a5cb7cc5fcb081ad8e"},{"code_id":"APK_RF","article_number":"187","version_date":"2002-07-24","article_text":"Определение, вынесенное арбитражным судом, исполняется немедленно, если иное не установлено настоящим Кодексом или арбитражным судом.","article_title":"Статья 187. Исполнение определения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fee8902cadeb4daeaa6691b9e45cfb82d0722734a88188a7ddac68297592433c"},{"code_id":"APK_RF","article_number":"188","version_date":"2002-07-24","article_text":"1. Определение арбитражного суда может быть обжаловано отдельно от обжалования судебного акта, которым заканчивается рассмотрение дела по существу, в случаях, если в соответствии с настоящим Кодексом предусмотрено обжалование этого определения, а также если это определение препятствует дальнейшему движению дела.\n\n2. В отношении определения, обжалование которого не предусмотрено настоящим Кодексом, а также в отношении протокольного определения могут быть заявлены возражения при обжаловании судебного акта, которым заканчивается рассмотрение дела по существу.","article_title":"Статья 188. Порядок и сроки обжалования определений","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a8c8f386c2b49a325de8de4751d893203b6326dbe35e8925a20475712207fcc5"},{"code_id":"APK_RF","article_number":"188.1","version_date":"2002-07-24","article_text":"1. При выявлении в ходе рассмотрения дела случаев, требующих устранения нарушения законодательства Российской Федерации государственным органом, органом местного самоуправления, иным органом, организацией, наделенной федеральным законом отдельными государственными или иными публичными полномочиями, должностным лицом, адвокатом, субъектом профессиональной деятельности, арбитражный суд вправе вынести частное определение.\n\n2. Частное определение арбитражного суда направляется в соответствующий орган, организацию, наделенную федеральным законом отдельными государственными или иными публичными полномочиями, должностному лицу, а в случае нарушения законодательства Российской Федерации адвокатом, субъектом профессиональной деятельности - соответственно в адвокатское образование, саморегулируемую организацию, которые в течение месяца со дня его получения обязаны сообщить о принятых ими мерах.\n\n3. Неисполнение частного определения арбитражного суда влечет за собой ответственность, предусмотренную законодательством Российской Федерации. Привлечение к ответственности указанных в части 1 настоящей статьи лиц не освобождает их от обязанности сообщить о мерах, принятых по частному определению арбитражного суда.\n\n(Дополнение статьей - Федеральный закон от 02.03.2016 № 47-ФЗ)\n\nРАЗДЕЛ III. ПРОИЗВОДСТВО В АРБИТРАЖНОМ СУДЕ ПЕРВОЙ ИНСТАНЦИИ ПО ДЕЛАМ, ВОЗНИКАЮЩИМ ИЗ АДМИНИСТРАТИВНЫХ И ИНЫХ ПУБЛИЧНЫХ ПРАВООТНОШЕНИЙ","article_title":"Статья 188.1. Частные определения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"40ff5a749a66f2812609e843fa58d4d72d378d2c22a78c4202fb1584ec9d9539"},{"code_id":"APK_RF","article_number":"189","version_date":"2002-07-24","article_text":"1. Дела, возникающие из административных и иных публичных правоотношений, рассматриваются по общим правилам искового производства, предусмотренным настоящим Кодексом, с особенностями, установленными в настоящем разделе, если иные правила административного судопроизводства не предусмотрены федеральным законом.","article_title":"Статья 189. Порядок рассмотрения дел, возникающих из административных и иных публичных правоотношений","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8cedee9da6e86f75496a0f485498d116a3afda609fbe29cec9554199307f8542"},{"code_id":"APK_RF","article_number":"19","version_date":"2002-07-24","article_text":"1. Арбитражные заседатели могут быть привлечены к рассмотрению дел в арбитражных судах первой инстанции в соответствии с настоящим Кодексом и другими федеральными законами по ходатайству стороны в связи с особой сложностью дела и (или) необходимостью использования специальных знаний в сфере экономики, финансов, управления.\n\n2. Ходатайство о рассмотрении дела с участием арбитражных заседателей должно содержать обоснование особой сложности дела и (или) необходимости использования специальных знаний и может быть заявлено стороной не позднее чем за один месяц до начала судебного разбирательства, в том числе при каждом новом рассмотрении дела.\n\nСуд обязан разъяснить сторонам их право заявлять такое ходатайство в определении о принятии искового заявления к производству суда и при подготовке дела к судебному разбирательству.\n\n3. Ходатайство о рассмотрении дела с участием арбитражных заседателей разрешается арбитражным судом в порядке, установленном статьей 159 настоящего Кодекса.\n\nВ случае, если ходатайство о рассмотрении дела с участием арбитражных заседателей удовлетворено, кандидатуры арбитражных заседателей определяются из списка арбитражных заседателей, утвержденного в установленном федеральным законом порядке, с учетом их специализации, путем случайной выборки с использованием автоматизированной информационной системы или иным способом, применяемым в арбитражном суде для формирования состава суда.\n\n4. Наличие случая, предусмотренного частями 3 и 4 статьи 18 настоящего Кодекса, является основанием для замены арбитражного заседателя. В этом случае другая кандидатура арбитражного заседателя определяется в порядке, установленном частью 3 настоящей статьи.\n\nЕсли после отвода одного или нескольких арбитражных заседателей невозможно сформировать состав суда для рассмотрения дела с участием арбитражных заседателей, указанное дело рассматривается судьей единолично.\n\nВ случае неявки в судебное заседание одного или двух арбитражных заседателей дело может быть рассмотрено судьей единолично, если стороны или их представители присутствуют в данном судебном заседании и не возражают против рассмотрения дела судьей единолично.\n\nЕсли хотя бы одна из сторон возражает против рассмотрения дела судьей единолично, суд объявляет перерыв в судебном заседании или откладывает судебное разбирательство. Если проведение нового судебного заседания невозможно вследствие неявки в судебное заседание одного или двух арбитражных заседателей, суд по ходатайству одной из сторон вправе вынести определение о рассмотрении дела судьей единолично и открыть судебное заседание в первой инстанции.\n\n5. При рассмотрении дела арбитражные заседатели пользуются правами и несут обязанности судьи.\n\n6. Судья и арбитражный заседатель при рассмотрении дела, разрешении всех вопросов, возникающих при рассмотрении дела и принятии судебных актов, пользуются равными процессуальными правами.\n\n7. Арбитражный заседатель не может быть председательствующим в судебном заседании.\n\n(Статья в редакции Федерального закона от 27.07.2010 № 228-ФЗ)","article_title":"Статья 19. Привлечение к рассмотрению дел арбитражных заседателей","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"24483ab7a2ef5527ab73e723109f16c0526283b2870dc33239bacad59022a0e8"},{"code_id":"APK_RF","article_number":"190","version_date":"2002-07-24","article_text":"1. Экономические споры, возникающие из административных и иных публичных правоотношений, могут быть урегулированы сторонами путем использования примирительных процедур по правилам, установленным в главе 15 настоящего Кодекса, поскольку иное не установлено настоящим Кодексом, другими законами и не вытекает из существа соответствующих правоотношений.\n\n2. В случаях, если до обращения в арбитражный суд с требованиями об оспаривании ненормативных правовых актов, решений и действий (бездействия) органов, осуществляющих публичные полномочия, и должностных лиц, о взыскании обязательных платежей и санкций стороны не использовали досудебное урегулирование спора, арбитражный суд вправе при согласии организации, индивидуального предпринимателя или гражданина в целях примирения сторон и уточнения фактических обстоятельств, снятия противоречий в позициях, в том числе путем проведения сверки взаимных расчетов, отложить судебное разбирательство в порядке, установленном настоящим Кодексом, предложив сторонам использовать примирительную процедуру, в том числе с участием судебного примирителя.\n\n3. Результатами примирения сторон по спорам, возникающим из административных и иных публичных правоотношений, могут быть, в частности:\n\n1) признание обстоятельств дела, соглашение сторон по обстоятельствам дела;\n\n2) соглашение сторон, содержащее квалификацию сделки, совершенной лицом, участвующим в деле, или статуса и характера деятельности этого лица;\n\n3) частичный или полный отказ от тр\n\nебований, частичное или полное признание требований, в том числе вследствие достижения сторонами соглашения об оценке обстоятельств в целом или их отдельных частей;\n\n4) мировое соглашение, если к полномочиям соответствующего административного органа, участвующего в деле, федеральным законом отнесено заключение мировых соглашений.\n\n(Статья в редакции Федерального закона от 26.07.2019 № 197-ФЗ)\n\n(Наименование в редакции Федерального закона от 15.02.2016 № 18-ФЗ)","article_title":"Статья 190. Примирение сторон по спорам, возникающим из административных и иных публичных правоотношений","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ed53bdf90a4d14766d16936c1db4f50d44ae4df7d8b8c2d572ec89bedf3c2258"},{"code_id":"APK_RF","article_number":"191","version_date":"2002-07-24","article_text":"1. Дела об оспаривании нормативных правовых актов федеральных органов исполнительной власти в сфере патентных прав и прав на селекционные достижения, права на топологии интегральных микросхем, права на секреты производства (ноу-хау), права на средства индивидуализации юридических лиц, товаров, работ, услуг и предприятий, права использования результатов интеллектуальной деятельности в составе единой технологии (далее в настоящей главе - нормативный правовой акт) рассматриваются Судом по интеллектуальным правам по общим правилам искового производства, предусмотренным настоящим Кодексом, с особенностями, установленными в настоящей главе.\n\n2. Производство по делам об оспаривании нормативных правовых актов возбуждается на основании заявлений заинтересованных лиц, обратившихся с требованием о признании такого оспариваемого акта недействующим.\n\n(Статья в редакции Федерального закона от 28.06.2014 № 186-ФЗ)","article_title":"Статья 191. Порядок рассмотрения дел об оспаривании нормативных правовых актов Судом по интеллектуальным правам","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"dddb9f06b74a746b2b865f639188ef5ddb3bef75156c618299664a6e235ae45d"},{"code_id":"APK_RF","article_number":"192","version_date":"2002-07-24","article_text":"1. Граждане, организации и иные лица вправе обратиться в Суд по интеллектуальным правам с заявлениями о признании недействующими нормативных правовых актов, если полагают, что такой оспариваемый нормативный правовой акт или отдельные его положения не соответствуют закону или иному нормативному правовому акту, имеющим большую юридическую силу, и нарушают их права и законные интересы.\n\n2. Прокурор, а также государственные органы, органы местного самоуправления, иные органы вправе обратиться в Суд по интеллектуальным правам в случаях, предусмотренных настоящим Кодексом, с заявлениями о признании нормативных правовых актов недействующими, если полагают, что такой оспариваемый акт или отдельные его положения не соответствуют закону или иному нормативному правовому акту, имеющим большую юридическую силу, и нарушают права и законные интересы граждан, организаций, иных лиц.\n\n3. Обращение заинтересованного лица в вышестоящий в порядке подчиненности орган или к должностному лицу не является обязательным условием для подачи заявления в Суд по интеллектуальным правам, если федеральным законом не установлено иное.\n\n(Статья в редакции Федерального закона от 28.06.2014 № 186-ФЗ)","article_title":"Статья 192. Право на обращение в Суд по интеллектуальным правам с заявлением о признании нормативного правового акта недействующим","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"483fa622213eb5737276eff51cf0aac822d917e69c0994e0d15b22711cb3183a"},{"code_id":"APK_RF","article_number":"193","version_date":"2002-07-24","article_text":"1. Заявление о признании нормативного правового акта недействующим должно соответствовать требованиям, предусмотренным частью 1, пунктами 1, 2 и 10 части 2, частью 3 статьи 125 настоящего Кодекса.\n\nВ заявлении должны быть также указаны:\n\n1) наименование федерального органа исполнительной власти, принявшего оспариваемый нормативный правовой акт;\n\n2) название, номер, дата принятия, источник опубликования и иные данные об оспариваемом нормативном правовом акте;\n\n3) права и законные интересы заявителя, которые, по его мнению, нарушаются оспариваемым актом или его отдельными положениями;\n\n4) название нормативного правового акта, который имеет большую юридическую силу и на соответствие которому надлежит проверить оспариваемый акт или его отдельные положения;\n\n5) требование заявителя о признании оспариваемого акта недействующим;\n\n6) перечень прилагаемых документов.\n\n2. К заявлению прилагаются документы, указанные в пунктах 1 - 5 статьи 126 настоящего Кодекса, а также текст оспариваемого нормативного правового акта.\n\n3. Подача заявления в Суд по интеллектуальным правам не приостанавливает действие оспариваемого нормативного правового акта.\n\n(Статья в редакции Федерального закона от 28.06.2014 № 186-ФЗ)","article_title":"Статья 193. Требования к заявлению о признании нормативного правового акта недействующим","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7cc50ad35cce141285de99e02f58871340c6678d665c533539a7e9d672f3cd85"},{"code_id":"APK_RF","article_number":"194","version_date":"2002-07-24","article_text":"1. Дело об оспаривании нормативного правового акта рассматривается коллегиальным составом судей в срок, не превышающий трех месяцев со дня поступления заявления в суд, включая срок на подготовку дела к судебному разбирательству и принятие решения по делу.\n\n2. Суд по интеллектуальным правам извещает о времени и месте судебного заседания заявителя, орган, принявший оспариваемый нормативный правовой акт, а также иных заинтересованных лиц. Неявка указанных лиц, извещенных надлежащим образом о времени и месте судебного заседания, не является препятствием для рассмотрения дела, если суд не признал их явку обязательной.\n\n3. Суд по интеллектуальным правам может признать обязательной явку в судебное заседание представителей государственных органов, органов местного самоуправления, иных органов, должностных лиц, принявших оспариваемый нормативный правовой акт, и вызвать их в судебное заседание для дачи объяснений.\n\nНеявка указанных лиц, вызванных в судебное заседание, является основанием для наложения штрафа в порядке и в размерах, которые установлены в главе 11 настоящего Кодекса.\n\n4. При рассмотрении дел об оспаривании нормативных правовых актов Суд по интеллектуальным правам в судебном заседании осуществляет проверку оспариваемого акта или его отдельного положения, устанавливает соответствие его федеральному конституционному закону, федеральному закону и иному нормативному правовому акту, имеющим большую юридическую силу, а также полномочия органа или лица, принявших оспариваемый нормативный правовой акт.\n\n5. Суд по интеллектуальным правам не связан доводами, содержащимися в заявлении об оспаривании нормативного правового акта, и проверяет оспариваемое положение в полном объеме.\n\n6. Обязанность доказывания соответствия оспариваемого нормативного правового акта федеральному конституционному закону, федеральному закону и иному нормативному правовому акту, имеющим большую юридическую силу, наличия у органа или должностного лица надлежащих полномочий на принятие оспариваемого акта, а также обстоятельств, послуживших основанием для его принятия, возлагается на орган, должностное лицо, которые приняли оспариваемый акт.\n\n7. В случае, если имеется вступившее в законную силу решение арбитражного суда или суда общей юрисдикции по ранее рассмотренному делу, проверившего по тем же основаниям соответствие оспариваемого нормативного правового акта иному нормативному правовому акту, имеющему большую юридическую силу, Суд по интеллектуальным правам прекращает производство по делу.\n\n8. Отказ заинтересованного лица, обратившегося в Суд по интеллектуальным правам с заявлением об оспаривании нормативного правового акта, от своего требования, признание требования органом или лицом, которые приняли оспариваемый акт, не препятствуют рассмотрению Судом по интеллектуальным правам дела по существу.\n\n(Статья в редакции Федерального закона от 28.06.2014 № 186-ФЗ)","article_title":"Статья 194. Судебное разбирательство по делу об оспаривании нормативного правового акта","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1cc04cb32b81b37b5fc3e09f490364d752d48d15e19519852e1cc9aa37afc7bd"},{"code_id":"APK_RF","article_number":"195","version_date":"2002-07-24","article_text":"1. Решение по делу об оспаривании нормативного правового акта принимается Судом по интеллектуальным правам по правилам, установленным в главе 20 настоящего Кодекса.\n\n2. По результатам рассмотрения дела об оспаривании нормативного правового акта Суд по интеллектуальным правам принимает одно из решений:\n\n1) о признании оспариваемого акта или отдельных его положений соответствующими иному нормативному правовому акту, имеющему большую юридическую силу;\n\n2) о признании оспариваемого нормативного правового акта или отдельных его положений не соответствующими иному нормативному правовому акту, имеющему большую юридическую силу, и не действующими полностью или в части.\n\n3. В резолютивной части решения по делу об оспаривании нормативного правового акта должны содержаться:\n\n1) наименование органа или лица, принявших оспариваемый акт, его название, номер, дата принятия акта;\n\n2) название нормативного правового акта, который имеет большую юридическую силу и на соответствие которому проверен оспариваемый акт;\n\n3) указание на признание оспариваемого акта соответствующим нормативному правовому акту, имеющему большую юридическую силу, и на отказ в удовлетворении заявленного требования или на признание оспариваемого акта не соответствующим нормативному правовому акту, имеющему большую юридическую силу, и не действующим полностью или в части.\n\n4. Решение Суда по интеллектуальным правам по делу об оспаривании нормативного правового акта вступает в законную силу немедленно после его принятия.\n\n5. Нормативный правовой акт или отдельные его положения, признанные Судом по интеллектуальным правам недействующими, не подлежат применению с момента вступления в законную силу решения суда и должны быть приведены органом или лицом, принявшими оспариваемый акт, в соответствие с законом или иным нормативным правовым актом, имеющими большую юридическую силу.\n\n6. Копии решения Суда по интеллектуальным правам в срок, не превышающий десяти дней со дня его принятия, направляются лицам, участвующим в деле.\n\n7. Вступившее в законную силу решение Суда по интеллектуальным правам по делу об оспаривании нормативного правового акта может быть обжаловано по правилам, установленным настоящим Кодексом.\n\n(Статья в редакции Федерального закона от 28.06.2014 № 186-ФЗ)","article_title":"Статья 195. Решение суда по делу об оспаривании нормативного правового акта","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a27c2010e227629bce6a42ac11885fcdc7e9a05549cb3906f4eef79c3e911d18"},{"code_id":"APK_RF","article_number":"195.1","version_date":"2002-07-24","article_text":"1. Дела об оспаривании актов федеральных органов исполнительной власти в сфере патентных прав и прав на селекционные достижения, права на топологии интегральных микросхем, права на секреты производства (ноу-хау), права на средства индивидуализации юридических лиц, товаров, работ, услуг и предприятий, права использования результатов интеллектуальной деятельности в составе единой технологии, содержащих разъяснения законодательства и обладающих нормативными свойствами (далее - акты, обладающие нормативными свойствами), рассматриваются Судом по интеллектуальным правам по общим правилам искового производства, предусмотренным настоящим Кодексом, с особенностями, установленными настоящей главой и определенными в настоящей статье.\n\n2. С заявлением о признании недействующим акта, обладающего нормативными свойствами, вправе обратиться лица, указанные в частях 1 и 2 статьи 192 настоящего Кодекса, если они полагают, что такой акт обладает нормативными свойствами и по своему содержанию не соответствует разъясняемым им нормативным положениям.\n\n3. При рассмотрении дел об оспаривании актов, обладающих нормативными свойствами, Суд по интеллектуальным правам устанавливает, обладает ли оспариваемый акт нормативными свойствами, позволяющими применить его неоднократно в качестве общеобязательного предписания в отношении неопределенного круга лиц, и соответствуют ли положения оспариваемого акта разъясняемым им нормативным положениям.\n\n4. Обязанность доказывания соответствия положений оспариваемого акта разъясняемым им нормативным положениям возлагается на орган или должностное лицо, которые приняли оспариваемый акт.\n\n5. По результатам рассмотрения дела об оспаривании акта, обладающего нормативными свойствами, Суд по интеллектуальным правам принимает одно из следующих решений:\n\n1) о признании оспариваемого акта полностью или в части не обладающим нормативными свойствами и соответствующим разъясняемым им нормативным положениям;\n\n2) о признании оспариваемого акта полностью или в части не соответствующим разъясняемым им нормативным положениям, устанавливающим не предусмотренные разъясняемыми нормативными положениями общеобязательные правила, распространяющиеся на неопределенный круг лиц и рассчитанные на неоднократное применение, и о признании этого акта не действующим полностью или в части.\n\n(Дополнение статьей - Федеральный закон от 15.02.2016 № 18-ФЗ)","article_title":"Статья 195.1. Рассмотрение дел об оспаривании актов, содержащих разъяснения законодательства и обладающих нормативными свойствами","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"42a2849010371b85a3336a2581f1dcea7b44a80d6ab8a3617795c120d6d1a116"},{"code_id":"APK_RF","article_number":"196","version_date":"2002-07-24","article_text":"Вступившее в законную силу решение Суда по интеллектуальным правам по делу об оспаривании нормативного правового акта или по делу об оспаривании акта, обладающего нормативными свойствами, направляется Судом по интеллектуальным правам в официальные издания федеральных органов исполнительной власти и другие официальные издания, в которых был опубликован оспариваемый акт, и подлежит незамедлительному опубликованию указанными изданиями. (В редакции Федерального закона от 17.04.2017 № 76-ФЗ)\n\n(Статья в редакции Федеральный закон от 15.02.2016 № 18-ФЗ)\n\n(Наименование в редакции Федерального закона от 27.07.2010 № 228-ФЗ)","article_title":"Статья 196. Опубликование решения Суда по интеллектуальным правам по делу об оспаривании нормативного правового акта или по делу об оспаривании акта, обладающего нормативными свойствами","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f136508057e4c0878798285a248fc7e2cfb0ff57a8232b8fbab00b3e91ed397d"},{"code_id":"APK_RF","article_number":"197","version_date":"2002-07-24","article_text":"(Наименование в редакции Федерального закона от 27.07.2010 № 228-ФЗ)","article_title":"Статья 197. Порядок рассмотрения дел об оспаривании ненормативных правовых актов, решений и действий (бездействия) государственных органов, органов местного самоуправления, иных органов, организаций, наделенных федеральным законом отдельными государственными или иными публичными полномочиями, должностных лиц","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0a953dd3cf2bc708c849f1f130426d87a16b81bc88b6c9cc7eb7e1e395c35c60"},{"code_id":"APK_RF","article_number":"199","version_date":"2002-07-24","article_text":"1. Заявление о признании ненормативного правового акта недействительным, решений и действий (бездействия) незаконными должно соответствовать требованиям, предусмотренным частью 1, пунктами 1, 2 и 10 части 2, частью 3 статьи 125 настоящего Кодекса.\n\nВ заявлении должны быть также указаны:\n\n1) наименование органа или лица, которые приняли оспариваемый акт, решение, совершили оспариваемые действия (бездействие);\n\n2) название, номер, дата принятия оспариваемого акта, решения, время совершения действий;\n\n3) права и законные интересы, которые, по мнению заявителя, нарушаются оспариваемым актом, решением и действием (бездействием);\n\n4) законы и иные нормативные правовые акты, которым, по мнению заявителя, не соответствуют оспариваемый акт, решение и действие (бездействие);\n\n5) требование заявителя о признании ненормативного правового акта недействительным, решений и действий (бездействия) незаконными.\n\nВ заявлении об оспаривании решений и действий (бездействия) должностного лица службы судебных приставов должны быть также указаны сведения об исполнительном документе, в связи с исполнением которого оспариваются решения и действия (бездействие) указанного должностного лица. (В редакции Федерального закона от 02.10.2007 № 225-ФЗ)\n\n2. К заявлению прилагаются документы, указанные в статье 126 настоящего Кодекса, а также текст оспариваемого акта, решения.\n\nК заявлению об оспаривании решений и действий (бездействия) должностного лица службы судебных приставов прилагаются, кроме того, уведомление о вручении или иные документы, подтверждающие направление копии заявления и необходимых доказательств указанному должностному лицу и другой стороне исполнительного производства. (В редакции Федерального закона от 02.10.2007 № 225-ФЗ)","article_title":"Статья 199. Требования к заявлению о признании ненормативного правового акта недействительным, решений и действий (бездействия) незаконными","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0a32e1b7c3b06dc7b35203d0664d109d68b20b79bd4407290dc454863116f94e"},{"code_id":"APK_RF","article_number":"2","version_date":"2002-07-24","article_text":"Задачами судопроизводства в арбитражных судах являются:\n\n1) защита нарушенных или оспариваемых прав и законных интересов лиц, осуществляющих предпринимательскую и иную экономическую деятельность, а также прав и законных интересов Российской Федерации, субъектов Российской Федерации, муниципальных образований в сфере предпринимательской и иной экономической деятельности, органов государственной власти Российской Федерации, органов государственной власти субъектов Российской Федерации, органов местного самоуправления, иных органов, должностных лиц в указанной сфере;\n\n2) обеспечение доступности правосудия в сфере предпринимательской и иной экономической деятельности;\n\n3) справедливое публичное судебное разбирательство в разумный срок независимым и беспристрастным судом; (В редакции Федерального закона от 30.04.2010 № 69-ФЗ)\n\n4) укрепление законности и предупреждение правонарушений в сфере предпринимательской и иной экономической деятельности;\n\n5) формирование уважительного отношения к закону и суду;\n\n6) содействие становлению и развитию партнерских деловых отношений, мирному урегулированию споров, формированию обычаев и этики делового оборота. (В редакции Федерального закона от 26.07.2019 № 197-ФЗ)","article_title":"Статья 2. Задачи судопроизводства в арбитражных судах","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8cd701b4b761ab88947dbd7ddf5ffd63c0b0efb1f8f4d09d4bdb154c429c4093"},{"code_id":"APK_RF","article_number":"20","version_date":"2002-07-24","article_text":"(Наименование в редакции Федерального закона от 27.07.2010 № 228-ФЗ)\n\n1. Вопросы, возникающие при рассмотрении дела судом в коллегиальном составе, разрешаются судьями большинством голосов. Никто из судей не вправе воздержаться от голосования. Судья - председательствующий в заседании - голосует последним.\n\n2. Судья, несогласный с мнением большинства судей, голосовавших за принятие судебного акта, обязан подписать этот судебный акт и вправе изложить в письменной форме свое особое мнение.\n\nСудья, голосовавший за принятый судебный акт по существу рассматриваемого судом вопроса, но оставшийся в меньшинстве при голосовании по какому-либо другому вопросу или по мотивировке принятого судебного акта, также вправе изложить в письменной форме свое особое мнение.\n\nПри изложении своего особого мнения судья не вправе сообщать кому бы то ни было сведения о содержании обсуждения при принятии судебного акта, о позиции отдельных судей, входивших в состав суда, и иным способом раскрывать тайну совещания судей.\n\nОсобое мнение судьи должно быть изготовлено в срок, не превышающий пяти дней со дня принятия решения по делу. Особое мнение судьи приобщается к материалам дела, но не оглашается.\n\n(Часть в редакции Федерального закона от 27.07.2010 № 228-ФЗ)","article_title":"Статья 20. Порядок разрешения вопросов судом в коллегиальном составе. Особое мнение судьи","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e2b2cf4ecf2d39148857eab4330d6e8e0f1aa55b414be24eed3dc7575a5b3e78"},{"code_id":"APK_RF","article_number":"200","version_date":"2002-07-24","article_text":"ений и действий (бездействия) органов, осуществляющих публичные полномочия, должностных лиц\n\n(Наименование в редакции Федерального закона от 27.07.2010 № 228-ФЗ)\n\nДела об оспаривании решений и действий (бездействия) должностного лица службы судебных приставов рассматриваются в срок, не превышающий десяти дней со дня поступления заявления в арбитражный суд, включая срок на подготовку дела к судебному разбирательству и принятие решения по делу. Указанный срок может быть продлен на основании мотивированного заявления судьи, рассматривающего дело, председателем арбитражного суда, заместителем председателя арбитражного суда до трех месяцев в связи с особой сложностью дела, со значительным числом участников арбитражного процесса. (В редакции  федеральных законов от 02.10.2007 № 225-ФЗ, от 25.12.2023 № 667-ФЗ)\n\nДела об оспаривании решений органов местного самоуправления о сносе самовольных построек или об их приведении в соответствие с предельными параметрами разрешенного строительства, реконструкции объектов капитального строительства, установленными правилами землепользования и застройки, документацией по планировке территории, или обязательными требованиями к параметрам объектов капитального строительства, установленными федеральными законами, об оспаривании решений органов государственной власти или органов местного самоуправления о прекращении вещных прав на земельные участки (права пожизненного наследуемого владения, права постоянного (бессрочного) пользования) в связи с неисполнением обязанностей по сносу самовольной постройки или ее приведению в соответствие с указанными параметрами и требованиями рассматриваются в срок, не превышающий одного месяца со дня поступления соответствующего заявления в арбитражный суд, включая срок на подготовку дела к судебному разбирательству и принятие решения по делу. (Дополнение абзацем - Федеральный закон от 03.08.2018 № 340-ФЗ)","article_title":"Статья 200. Судебное разбирательство по делам об оспаривании ненормативных правовых актов, реш","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d3c45c2cd312f4a1038cc4f242b20330ed02323d6cac12d36a1aaadf02566af8"},{"code_id":"APK_RF","article_number":"201","version_date":"2002-07-24","article_text":"(Наименование в редакции Федерального закона от 27.07.2010 № 228-ФЗ)\n\n1) наименование органа или лица, принявших оспариваемый акт, решение; название, номер, дата принятия оспариваемого акта, решения;\n\n2) название закона или иного нормативного правового акта, на соответствие которому проверены оспариваемый акт, решение;\n\n3) указание на признание оспариваемого акта недействительным или решения незаконным полностью или в части и обязанность устранить допущенные нарушения прав и законных интересов заявителя либо на отказ в удовлетворении требования заявителя полностью или в части.\n\n1) наименование органа или лица, совершивших оспариваемые действия (бездействие) и отказавших в совершении действий, принятии решений; сведения о действиях (бездействии), решениях;\n\n2) название закона или иного нормативного правового акта, на соответствие которым проверены оспариваемые действия (бездействие), решения;\n\n3) указание на признание оспариваемых действий (бездействия) незаконными и обязанность соответствующих органов, осуществляющих публичные полномочия, должностных лиц совершить определенные действия, принять решения или иным образом устранить допущенные нарушения прав и законных интересов заявителя в установленный судом срок либо на отказ в удовлетворении требования заявителя полностью или в части. (В редакции Федерального закона от 27.07.2010 № 228-ФЗ)","article_title":"Статья 201. Решение арбитражного суда по делу об оспаривании ненормативных правовых актов, решений и действий (бездействия) органов, осуществляющих публичные полномочия, должностных лиц","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"11651f5cc994222911bdacd0b4bebbd26dd6f876e94248a710386b0ff4f41efc"},{"code_id":"APK_RF","article_number":"203","version_date":"2002-07-24","article_text":"Заявление о привлечении к административной ответственности подается в арбитражный суд по адресу или месту жительства лица, в отношении которого составлен протокол об административном правонарушении. В случае, если лицо, в отношении которого составлен протокол об административном правонарушении, привлекается за административное правонарушение, совершенное вне места его нахождения или места его жительства, указанное заявление может быть подано в арбитражный суд по месту совершения административного правонарушения. (В редакции федеральных законов от 27.07.2010 № 228-ФЗ, от 28.11.2018 № 451-ФЗ)","article_title":"Статья 203. Подача заявления о привлечении к административной ответственности","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a486ec659e8421069a617f23fb46ecb6af1dfc37863e94316c25a20b101409dd"},{"code_id":"APK_RF","article_number":"204","version_date":"2002-07-24","article_text":"1. Заявление о привлечении к административной ответственности лиц, осуществляющих предпринимательскую и иную экономическую деятельность, должно соответствовать требованиям, предусмотренным частью 1, пунктами 1, 2 и 10 части 2, частью 3 статьи 125 настоящего Кодекса.\n\nВ заявлении должны быть также указаны:\n\n1) дата и место совершения действий, послуживших основанием для составления протокола об административном правонарушении;\n\n2) должность, фамилия и инициалы лица, составившего протокол об административном правонарушении;\n\n3) сведения о лице, в отношении которого составлен протокол об административном правонарушении;\n\n4) нормы закона, предусматривающего административную ответственность за действия, послужившие основанием для составления протокола об административном правонарушении;\n\n5) требование заявителя о привлечении к административной ответственности.\n\n2. К заявлению прилагаются протокол об административном правонарушении и прилагаемые к протоколу документы, а также уведомление о вручении или иной документ, подтверждающие направление копии заявления лицу, в отношении которого составлен протокол об административном правонарушении.","article_title":"Статья 204. Требования к заявлению о привлечении к административной ответственности","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7802377a1009ddfab7e239273537adbe6cf9b4b191057b0bcc5ff234120a1833"},{"code_id":"APK_RF","article_number":"205","version_date":"2002-07-24","article_text":"В случае непредставления административным органом, составившим протокол, доказательств, необходимых для рассмотрения дела и принятия решения, арбитражный суд может истребовать доказательства от указанного органа по своей инициативе.","article_title":"Статья 205. Судебное разбирательство по делам о привлечении к административной ответственности","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1f8e044d3d4b236973a8fbe4cfd6f5b0d6e68f38c43390102b205759fe206a6c"},{"code_id":"APK_RF","article_number":"206","version_date":"2002-07-24","article_text":"1. Решение по делу о привлечении к административной ответственности принимается арбитражным судом по правилам, установленным в главе 20 настоящего Кодекса.\n\n2. По результатам рассмотрения заявления о привлечении к административной ответственности арбитражный суд принимает решение о привлечении к административной ответственности или об отказе в удовлетворении требования административного органа о привлечении к административной ответственности.\n\n3. В резолютивной части решения о привлечении к административной ответственности должны содержаться:\n\n1) наименование лица, привлеченного к административной ответственности, его адрес или место жительства, сведения о его государственной регистрации в качестве юридического лица или индивидуального предпринимателя; (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n2) нормы закона, на основании которых данное лицо привлекается к административной ответственности;\n\n3) вид административного наказания и санкции, возложенные на лицо, привлеченное к административной ответственности.\n\n4. Решение по делу о привлечении к административной ответственности вступает в законную силу по истечении десяти дней со дня его принятия, если не подана апелляционная жалоба.\n\nВ случае подачи апелляционной жалобы решение, если оно не изменено или не отменено, вступает в законную силу со дня принятия постановления арбитражным судом апелляционной инстанции.\n\nВ других случаях решения по делам о привлечении к административной ответственности обжалуются в порядке, установленном статьей 181 настоящего Кодекса.\n\nАбзац. (Дополнение абзацем - Федеральный закон от 28.06.2014 № 186-ФЗ) (Утратил силу - Федеральный закон от 22.11.2016 № 393-ФЗ)\n\n(Дополнение частью - Федеральный закон от 27.07.2010 № 228-ФЗ)\n\n5. Копия решения арбитражного суда по делу о привлечении к административной ответственности направляется арбитражным судом в трехдневный срок со дня его принятия лицам, участвующим в деле. Арбитражный суд может направить копию решения также в вышестоящий в порядке подчиненности административный орган.","article_title":"Статья 206. Решение арбитражного суда по делу о привлечении к административной ответственности","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"53740a1e54302582ec750aa8f29176ce58aaccf2905a9a739951f87b71d6daf3"},{"code_id":"APK_RF","article_number":"207","version_date":"2002-07-24","article_text":"1. Дела об оспаривании решений государственных органов, иных органов, должностных лиц, уполномоченных в соответствии с федеральным зак\n\nоном рассматривать дела об административных правонарушениях (далее в параграфе 2 главы 25, пункте 4 части 1 статьи 227 настоящего Кодекса - административные органы), о привлечении к административной ответственности лиц, осуществляющих предпринимательскую и иную экономическую деятельность, рассматриваются арбитражным судом по общим правилам искового производства, предусмотренным настоящим Кодексом, с особенностями, установленными в настоящей главе и федеральном законе об административных правонарушениях. (В редакции Федерального закона от 25.06.2012 № 86-ФЗ)","article_title":"Статья 207. Порядок рассмотрения дел об оспаривании решений административных органов о привлечении к административной ответственности","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b09e913a4ba26ffbfab72dc6d6c860a94a9a9da503114fa830e3d83e0dc1a8c5"},{"code_id":"APK_RF","article_number":"208","version_date":"2002-07-24","article_text":"В случае пропуска указанного срока он может быть восстановлен судом по ходатайству заявителя.","article_title":"Статья 208. Подача заявления об оспаривании решения административного органа о привлечении к административной ответственности","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0cd71292b482af83ef3212cd490f600b286154c53b5f248fcd4aab1a0db238c4"},{"code_id":"APK_RF","article_number":"209","version_date":"2002-07-24","article_text":"1. Заявление об оспаривании решения административного органа о привлечении к административной ответственности должно соответствовать требованиям, предусмотренным частью 1, пунктами 1, 2 и 10 части 2, частью 3 статьи 125 настоящего Кодекса.\n\nВ заявлении должны быть также указаны:\n\n1) наименование административного органа, принявшего оспариваемое решение;\n\n2) название, номер, дата принятия оспариваемого решения и иные сведения о нем;\n\n3) права и законные интересы заявителя, которые нарушены, по его мнению, оспариваемым решением;\n\n4) требование заявителя и основания, по которым он оспаривает решение административного органа.\n\n2. К заявлению об оспаривании решения административного органа прилагаются текст оспариваемого решения, а также уведомление о вручении или иной документ, подтверждающие направление копии заявления об оспаривании решения в административный орган, его принявший.","article_title":"Статья 209. Требования к заявлению об оспаривании решения административного органа о привлечении к административной ответственности","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"166cd53dda0bffea7a239f1e15d1756db3fc9641c34d4d9c522aee15735772cd"},{"code_id":"APK_RF","article_number":"21","version_date":"2002-07-24","article_text":"1. Судья не может участвовать в рассмотрении дела и подлежит отводу, если он:\n\n1) при предыдущем рассмотрении данного дела участвовал в нем в качестве судьи и его повторное участие в рассмотрении дела в соответствии с требованиями настоящего Кодекса является недопустимым;\n\n2) при предыдущем рассмотрении данного дела участвовал в нем в качестве прокурора, помощника судьи, секретаря судебного заседания, представителя, эксперта, специалиста, переводчика или свидетеля; (В редакции Федерального закона от 08.12.2011 № 422-ФЗ)\n\n3) при предыдущем рассмотрении данного дела участвовал в нем в качестве судьи иностранного суда, третейского суда или арбитража;\n\n31) являлся судебны\n\nм примирителем по данному делу; (Дополнение пунктом - Федеральный закон от 26.07.2019 № 197-ФЗ)\n\n4) является родственником лица, участвующего в деле, или его представителя;\n\n5) лично, прямо или косвенно заинтересован в исходе дела либо имеются иные обстоятельства, которые могут вызвать сомнение в его беспристрастности;\n\n6) находится или ранее находился в служебной или иной зависимости от лица, участвующего в деле, или его представителя;\n\n7) делал публичные заявления или давал оценку по существу рассматриваемого дела.\n\n2. В состав арбитражного суда, рассматривающего дело, не могут входить лица, являющиеся родственниками.","article_title":"Статья 21. Отвод судьи","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1437f3e0ba501003e8e23dafec0bd0b00500b83d35fe186b3a4754bfa5b1c7b2"},{"code_id":"APK_RF","article_number":"211","version_date":"2002-07-24","article_text":"1. Решение по делу об оспаривании решения административного органа о привлечении к административной ответственности принимается арбитражным судом по правилам, установленным в главе 20 настоящего Кодекса.\n\n2. В случае, если при рассмотрении заявления об оспаривании решения административного органа о привлечении к административной ответственности арбитражный суд установит, что оспариваемое решение или порядок его принятия не соответствует закону, либо отсутствуют основания для привлечения к административной ответственности или применения конкретной меры ответственности, либо оспариваемое решение принято органом или должностным лицом с превышением их полномочий, суд принимает решение о признании незаконным и об отмене оспариваемого решения полностью или в части либо об изменении решения.\n\n3. В случае, если при рассмотрении заявления об оспаривании решения административного органа о привлечении к административной ответственности арбитражный суд установит, что решение административного органа о привлечении к административной ответственности является законным и обоснованным, суд принимает решение об отказе в удовлетворении требования заявителя.\n\n4. В резолютивной части решения по делу об оспаривании решения административного органа должны содержаться:\n\n1) название, номер, дата и место принятия, другие необходимые сведения об оспариваемом решении;\n\n2) наименование лица, привлеченного к административной ответственности, его адрес или место жительства, сведения о его государственной регистрации в качестве юридического лица или индивидуального предпринимателя; (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n3) указание на признание решения незаконным и его отмену полностью или в части, либо на отказ в удовлетворении требования заявителя полностью или в части, либо на меру ответственности, если она изменена судом.\n\n5. Решение арбитражного суда вступает в законную силу по истечении десяти дней со дня его принятия, если не подана апелляционная жалоба.\n\nВ случае подачи апелляционной жалобы решение, если оно не изменено или не отменено, вступает в законную силу со дня принятия постановления арбитражным судом апелляционной инстанции.\n\nВ других случаях решения по делам об оспаривании решений административных органов о привлечении к административной ответственности обжалуются в порядке, установленном статьей 181 настоящего Кодекса.\n\nАбзац. (Дополнение абзацем - Федеральный закон от 28.06.2014 № 186-ФЗ) (Утратил силу - Федеральный закон от 22.11.2016 № 393-ФЗ)\n\n(Дополнение частью - Федеральный закон от 27.07.2010 № 228-ФЗ)\n\n6. Копия решения направляется арбитражным судом в трехдневный срок со дня его принятия лицам, участвующим в деле. Арбитражный суд может направить копию решения также в вышестоящий в порядке подчиненности административный орган.","article_title":"Статья 211. Решение арбитражного суда по делу об оспаривании решения административного органа о привлечении к административной ответственности","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"712f5c654f8f005fc466da7036b14717f5717e68b61236d10cc38f583776a40a"},{"code_id":"APK_RF","article_number":"213","version_date":"2002-07-24","article_text":"1. Государственные органы, органы местного самоуправления, иные органы, наделенные в соответствии с федеральным законом контрольными функциями (далее - контрольные органы), вправе обратиться в арбитражный суд с заявлением о взыскании с лиц, осуществляющих предпринимательскую и иную экономическую деятельность, установленных законом обязательных платежей и санкций, если федеральным законом не предусмотрен иной порядок их взыскания.\n\n2. Заявление о взыскании подается в арбитражный суд, если не исполнено требование заявителя об уплате взыскиваемой суммы в добровольном порядке или пропущен указанный в таком требовании срок уплаты.","article_title":"Статья 213. Право на обращение в арбитражный суд с заявлением о взыскании обязательных платежей и санкций","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"54b895e11263d6a9d7a2fe50c5d840c8f0cb75d05e9b0cab04039fbd3a1863f8"},{"code_id":"APK_RF","article_number":"214","version_date":"2002-07-24","article_text":"1. Заявление о взыскании обязательных платежей и санкций должно соответствовать требованиям, предусмотренным частью 1, пунктами 1, 2 и 10 части 2, частью 3 статьи 125 настоящего Кодекса.\n\nВ заявлении должны быть также указаны:\n\n1) наименование платежа, подлежащего взысканию, размер и расчет его суммы;\n\n2) нормы федерального закона и иного нормативного правового акта, предусматривающие уплату платежа;\n\n3) сведения о направлении требования об уплате платежа в добровольном порядке.\n\n2. К заявлению о взыскании обязательных платежей и санкций прилагаются документы, указанные в пунктах 1 - 5 статьи 126 настоящего Кодекса, а также документ, подтверждающий направление заявителем требования об уплате взыскиваемого платежа в добровольном порядке.","article_title":"Статья 214. Требования к заявлению о взыскании обязательных платежей и санкций","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e70557b982a9a9a1011819956338b9d8ed36788da1e0504b1934ed92b9096fd8"},{"code_id":"APK_RF","article_number":"215","version_date":"2002-07-24","article_text":"Неявка указанных лиц, извещенных надлежащим образом о времени и месте судебного заседания, не является препятствием для рассмотрения дела, если суд не признал их явку обязательной.\n\nНеявка указанных лиц, вызванных в судебное заседание, является основанием для наложения штрафа в порядке и в размере, которые установлены в главе 11 настоящего Кодекса.","article_title":"Статья 215. Судебное разбирательство по делам о взыскании обязательных платежей и санкций","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a9d23f9828e18c6381a8926a4ea5cce055b2ec434d51878f7d30b66c9c7869c4"},{"code_id":"APK_RF","article_number":"216","version_date":"2002-07-24","article_text":"1. Решение арбитражного суда по делу о взыскании обязательных платежей и санкций принимается по правилам, установленным в главе 20 настоящего Кодекса.\n\n2. При удовлетворении требования о взыскании обязательных платежей и санкций в резолютивной части решения должны быть указаны:\n\n1) наименование лица, обязанного уплатить сумму задолженности, его адрес или место жительства, сведения о его государственной регистрации; (В редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n2) общий размер подлежащей взысканию денежной суммы с определением отдельно основной задолженности и санкций.\n\nРАЗДЕЛ IV. ОСОБЕННОСТИ ПРОИЗВОДСТВА В АРБИТРАЖНОМ СУДЕ ПО ОТДЕЛЬНЫМ КАТЕГОРИЯМ ДЕЛ","article_title":"Статья 216. Решение арбитражного суда по делу о взыскании обязательных платежей и санкций","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"93dffa32380988133389c464c7d51e18c6a38133e70bafd71761f11b0bebf139"},{"code_id":"APK_RF","article_number":"217","version_date":"2002-07-24","article_text":"1. Дела об установлении фактов, имеющих юридическое значение, рассматриваются арбитражным судом по общим правилам искового производства, установленным настоящим Кодексом, с особенностями, предусмотренными в настоящей главе.\n\n2. Производство по делам об установлении фактов, имеющих юридическое значение, возбуждается в арбитражном суде на основании заявлений об установлении фактов, имеющих юридическое значение.\n\n3. В случае, если при рассмотрении дела об установлении фактов, имеющих юридическое значение, выясняется, что возник спор о праве, арбитражный суд оставляет заявление об установлении фактов, имеющих юридическое значение, без рассмотрения, о чем выносит определение. В определении заявителю и другим заинтересованным лицам разъясняется их право разрешить спор в порядке искового производства.","article_title":"Статья 217. Порядок рассмотрения дел об установлении фактов, имеющих юридическое значение","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e6bbcd99a99ed1fc61ea29d118e26998108205f8a82b58ff8e1202f8c7569b1a"},{"code_id":"APK_RF","article_number":"218","version_date":"2002-07-24","article_text":"1. Арбитражный суд устанавливает факты, имеющие юридическое значение для возникновения, изменения или прекращения прав юридических лиц и индивидуальных предпринимателей в сфере предпринимательской и иной экономической деятельности.\n\n2. Арбитражный суд рассматривает дела об установлении:\n\n1) факта владения и пользования юридическим лицом или индивидуальным предпринимателем недвижимым имуществом как своим собственным;\n\n2) факта государственной регистрации юридического лица или индивидуального предпринимателя в определенное время и в определенном месте;\n\n3) факта принадлежности правоустанавливающего документа, действующего в сфере предпринимательской и иной экономической деятельности, юридическому лицу или индивидуальному предпринимателю, если наименование юридического лица, имя, отчество или фамилия индивидуального предпринимателя, указанные в документе, не совпадают с наименованием юридического лица по его учредительному документу, именем, отчеством или фамилией индивидуального предпринимателя по его паспорту или свидетельству о рождении;\n\n4) других фактов, порождающих юридические последствия в сфере предпринимательской и иной экономической деятельности.","article_title":"Статья 218. Дела об установлении фактов, имеющих юридическое значение","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"146df9a6093d236985e4e16fe13b480ea4c748dd8696b5be85a3c886c9024200"},{"code_id":"APK_RF","article_number":"219","version_date":"2002-07-24","article_text":"1. Юридическое лицо или индивидуальный предприниматель вправе обратиться в арбитражный суд с заявлением об установлении фактов, имеющих юридическое значение, только если у заявителя отсутствует возможность получить или восстановить надлежащие документы, удостоверяющие эти факты, и если федеральным законом или иным нормативным правовым актом не предусмотрен иной внесудебный порядок установления соответствующих фактов.","article_title":"Статья 219. Право на обращение в арбитражный суд с заявлением об установлении фактов, имеющих юридическое значение","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5853c78138c11a470c1ec5d53d04e3e780e1e479918ca49701a8b36942d17560"},{"code_id":"APK_RF","article_number":"22","version_date":"2002-07-24","article_text":"1. Судья, принимавший участие в рассмотрении дела в арбитражном суде первой инстанции, не может участвовать в рассмотрении этого дела в судах апелляционной и кассационной инстанций, а также в порядке надзора.\n\n2. Судья, принимавший участие в рассмотрении дела в арбитражном суде апелляционной инстанции, не может участвовать в рассмотрении этого дела в судах первой и кассационной инстанций, а также в порядке надзора.\n\n3. Судья, принимавший участие в рассмотрении дела в арбитражном суде кассационной инстанции, не может участвовать в рассмотрении этого дела в судах первой и апелляционной инстанций, а также в порядке надзора.\n\n4. Судья, принимавший участие в рассмотрении дела в порядке надзора, не может участвовать в рассмотрении этого дела в судах первой, апелляционной и кассационной инстанций.","article_title":"Статья 22. Недопустимость повторного участия судьи в рассмотрении дела","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8bdae3e6a59a30e16471209d4979aa45bb31a2579e96eb9d79c59b8c9dd77413"},{"code_id":"APK_RF","article_number":"220","version_date":"2002-07-24","article_text":"1. Заявление об установлении фактов, имеющих юридическое значение, должно соответствовать требованиям, предусмотренным частью 1, пунктами 1, 2 и 10 части 2 статьи 125 настоящего Кодекса.\n\nВ заявлении должны быть также указаны:\n\n1) факт, об установлении которого ходатайствует заявитель;\n\n2) нормы закона, предусматривающего, что данный факт порождает юридические последствия в сфере предпринимательской и иной экономической деятельности;\n\n3) обоснование необходимости установления данного факта;\n\n4) доказательства, подтверждающие невозможность получения заявителем надлежащих доказательств или восстановления утраченных документов.\n\n2. К заявлению об установлении фактов, имеющих юридическое значение, прилагаются документы, предусмотренные пунктами 2 - 5 статьи 126 настоящего Кодекса.","article_title":"Статья 220. Требования к заявлению об установлении фактов, имеющих юридическое значение","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"98ba3590a50166d901856bfe2bb0b8581e938a9589729c8a5d82a55e478d8fe8"},{"code_id":"APK_RF","article_number":"221","version_date":"2002-07-24","article_text":"1. Дела об установлении фактов, имеющих юридическое значение, рассматриваются судьей единолично в судебном заседании с участием заявителя и других заинтересованных лиц. К их рассмотрению не могут привлекаться арбитражные заседатели.\n\n2. При подготовке дела к су\n\nдебному разбирательству судья определяет круг заинтересованных по делу лиц, права которых может затронуть решение об установлении факта, имеющего юридическое значение, извещает этих лиц о производстве по делу, рассматривает вопрос о привлечении их к участию в деле, извещает о времени и месте судебного заседания.\n\n3. При рассмотрении дела об установлении факта, имеющего юридическое значение, арбитражный суд в судебном заседании проверяет, не предусмотрен ли законом или иным нормативным правовым актом иной внесудебный порядок установления данного факта, имелась ли у заявителя другая возможность получить или восстановить необходимые документы, устанавливает, порождает ли данный факт юридически значимые последствия для заявителя в связи с осуществлением им предпринимательской или иной экономической деятельности, выясняет, не затрагивает ли права других лиц установление требуемого факта, не возник ли спор о праве.\n\n4. В случае, если в ходе судебного разбирательства по делу об установлении факта, имеющего юридическое значение, выяснится, что возник спор о праве, арбитражный суд оставляет заявление об установлении факта, имеющего юридическое значение, без рассмотрения, о чем выносит определение.\n\nВ определении заявителю и другим заинтересованным по делу лицам разъясняется их право разрешить спор в порядке искового производства.","article_title":"Статья 221. Судебное разбирательство по делам об установлении фактов, имеющих юридическое значение","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cf0da91d21bd65ba118de19af4cf1097bbad85c60e1ac7a75dd6e36c14e4033a"}]$law7d0003$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
insert into law7_mirror.article_versions(code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,source_commit,imported_at)
select code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,'70a1d8fc6b27b67ad7f12f03f017d02b5f68a0c895447159039800965895f8b2',now() from j
on conflict (code_id,article_number,version_date) do update set article_text=excluded.article_text,article_title=excluded.article_title,amendment_eo_number=excluded.amendment_eo_number,amendment_date=excluded.amendment_date,is_current=excluded.is_current,is_repealed=excluded.is_repealed,repealed_date=excluded.repealed_date,text_hash=excluded.text_hash,source_commit=excluded.source_commit,imported_at=now();
commit;
